// src/pages/DeliveryDetailsPage.tsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";

interface Delivery {
  _id: string;
  customerId: string;
  status: string;
  driverId: string;
  address: string;
}

export default function DeliveryDetailsPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [delivery, setDelivery] = useState<Delivery | null>(null);

  useEffect(() => {
    if (!id) return;
    axios
      .get<Delivery>(`http://localhost:5000/api/delivery/${id}`)
      .then((res) => setDelivery(res.data))
      .catch(() => alert("❌ Failed to load delivery details."));
  }, [id]);

  if (!delivery) {
    return <div style={loading}>Loading delivery details…</div>;
  }

  return (
    <div style={container}>
      <header style={header}>
        <h1 style={headerTitle}>📦 Delivery Details</h1>
      </header>

      <main style={main}>
        <div style={card}>
          <p><strong>Customer ID:</strong> {delivery.customerId}</p>
          <p><strong>Status:</strong> {delivery.status}</p>
          <p><strong>Driver ID:</strong> {delivery.driverId}</p>
          <p><strong>Delivery Address:</strong> {delivery.address}</p>

          <div style={btnGroup}>
            <button style={backBtn} onClick={() => navigate("/dashboard")}>
              ← Back to Dashboard
            </button>
            <button style={trackBtn} onClick={() => navigate(`/tracking/${delivery._id}`)}>
              🚚 Track Delivery
            </button>
            <button
              style={mapsBtn}
              onClick={() =>
                window.open(
                  `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
                    delivery.address
                  )}`,
                  "_blank"
                )
              }
            >
              📍 Open in Google Maps
            </button>
          </div>
        </div>
      </main>

      <footer style={footer}>© 2025 Delivery Dashboard</footer>
    </div>
  );
}

// Layout
const container: React.CSSProperties = {
  display: "flex",
  flexDirection: "column",
  minHeight: "100vh",
  fontFamily: "Arial, sans-serif",
};
const header: React.CSSProperties = {
  background: "#e1f5fe",
  padding: "16px 24px",
  textAlign: "center",
};
const headerTitle: React.CSSProperties = {
  margin: 0,
  fontSize: "1.75rem",
  color: "#01579b",
};
const main: React.CSSProperties = {
  flex: 1,
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  background: "#fafafa",
  padding: "20px",
};
const card: React.CSSProperties = {
  background: "#fff",
  padding: "24px",
  borderRadius: "8px",
  boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
  maxWidth: "500px",
  width: "100%",
  textAlign: "center",
  lineHeight: 1.6,
};
const btnGroup: React.CSSProperties = {
  marginTop: "20px",
  display: "flex",
  justifyContent: "center",
  gap: "12px",
  flexWrap: "wrap",
};
const baseBtn: React.CSSProperties = {
  padding: "10px 16px",
  border: "none",
  borderRadius: "4px",
  cursor: "pointer",
  fontSize: "0.9rem",
};
const backBtn: React.CSSProperties = {
  ...baseBtn,
  background: "#6c757d",
  color: "#fff",
};
const trackBtn: React.CSSProperties = {
  ...baseBtn,
  background: "#0288d1",
  color: "#fff",
};
const mapsBtn: React.CSSProperties = {
  ...baseBtn,
  background: "#0288d1",
  color: "#fff",
};
const footer: React.CSSProperties = {
  background: "#e1f5fe",
  padding: "12px 0",
  textAlign: "center",
};
const loading: React.CSSProperties = {
  padding: "40px",
  textAlign: "center",
  fontSize: "1.2rem",
};
